
DROP TABLE IF EXISTS cost_centers;

CREATE TABLE cost_centers (
    -- Identity
    cc_id               SERIAL          PRIMARY KEY,
    cc_code             VARCHAR(20)     NOT NULL UNIQUE,      -- SAP-style: KS-ORG-0001
    cc_name             VARCHAR(120)    NOT NULL,

    -- Classification
    cc_type             VARCHAR(20)     NOT NULL,             -- COST | PROFIT | INVEST | OVERHEAD
    cc_type_label       VARCHAR(40)     NOT NULL,             -- Human-readable type name
    status              VARCHAR(20)     NOT NULL DEFAULT 'ACTIVE',  -- ACTIVE | INACTIVE | BLOCKED

    -- Organisation
    org_unit_code       VARCHAR(10)     NOT NULL,             -- FIN | IT | HR | OPS ...
    org_unit_name       VARCHAR(80)     NOT NULL,
    region_code         VARCHAR(10)     NOT NULL,             -- DE-BY | AT-WI | CH-ZH ...
    region_name         VARCHAR(80)     NOT NULL,
    company_code        VARCHAR(10)     NOT NULL,             -- 1000 | 2000 | 3000
    company_name        VARCHAR(80)     NOT NULL,

    -- Responsibility
    responsible_person  VARCHAR(80)     NOT NULL,
    deputy_person       VARCHAR(80)         NULL,
    controlling_person  VARCHAR(80)         NULL,

    -- Validity
    valid_from          DATE            NOT NULL,
    valid_to            DATE                NULL,             -- NULL = no end date (open-ended)

    -- Hierarchy
    hierarchy_level     VARCHAR(5)      NOT NULL DEFAULT '1', -- 1 | 2 | 3
    parent_cc_code      VARCHAR(20)         NULL,             -- NULL for top-level CCs

    -- Financials
    budget_eur          NUMERIC(15,2)   NOT NULL,
    actual_eur          NUMERIC(15,2)   NOT NULL,
    currency            VARCHAR(5)      NOT NULL DEFAULT 'EUR',

    -- Audit
    created_at          DATE            NOT NULL,
    modified_at         DATE            NOT NULL,

    -- Constraints
    CONSTRAINT chk_status       CHECK (status IN ('ACTIVE','INACTIVE','BLOCKED')),
    CONSTRAINT chk_cc_type      CHECK (cc_type IN ('COST','PROFIT','INVEST','OVERHEAD')),
    CONSTRAINT chk_valid_range  CHECK (valid_to IS NULL OR valid_to > valid_from),
    CONSTRAINT chk_hierarchy    CHECK (hierarchy_level IN ('1','2','3')),
    CONSTRAINT chk_currency     CHECK (currency = 'EUR')
);

-- Indexes useful for the kinds of queries the chat agent will generate
CREATE INDEX idx_cc_status          ON cost_centers (status);
CREATE INDEX idx_cc_org_unit        ON cost_centers (org_unit_code);
CREATE INDEX idx_cc_region          ON cost_centers (region_code);
CREATE INDEX idx_cc_company         ON cost_centers (company_code);
CREATE INDEX idx_cc_responsible     ON cost_centers (responsible_person);
CREATE INDEX idx_cc_type            ON cost_centers (cc_type);
CREATE INDEX idx_cc_valid_from      ON cost_centers (valid_from);
CREATE INDEX idx_cc_hierarchy       ON cost_centers (hierarchy_level);


-- Quick sanity check — run after seeding:
SELECT status, COUNT(*) AS cnt, ROUND(AVG(budget_eur)) AS avg_budget
FROM cost_centers
GROUP BY status
ORDER BY status;